"""Test the Tochal-only schema upgrade in a disposable, network-isolated PostgreSQL."""
import argparse
from pathlib import Path
import re
import subprocess
import time
import unittest
import uuid

ROOT = Path(__file__).resolve().parents[3]
INSTALLER = (ROOT / 'deployment/tochal-geography-schema.sql').read_text(encoding='utf-8')
PERMISSIONS = (ROOT / 'deployment/tochal-geography-permissions.sql').read_text(encoding='utf-8')
FIXTURE = '''
CREATE SCHEMA "references";
CREATE TABLE "references".provinces (
 "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Name" varchar(200) NOT NULL,
 "NameEn" varchar(200) NOT NULL, "Slug" varchar(200) NOT NULL UNIQUE,
 "SortOrder" int NOT NULL, "IsActive" boolean NOT NULL);
CREATE TABLE "references".cities (
 "Id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "Name" varchar(200) NOT NULL,
 "NameEn" varchar(200) NOT NULL, "Slug" varchar(200) NOT NULL,
 "ProvinceId" int NOT NULL REFERENCES "references".provinces("Id"),
 "SortOrder" int NOT NULL, "IsActive" boolean NOT NULL);
INSERT INTO "references".provinces VALUES (1,'تهران','Tehran','tehran',1,true);
INSERT INTO "references".cities VALUES (1,'تهران','Tehran','tehran',1,1,true);
SELECT setval(pg_get_serial_sequence('"references".cities','Id'),900000);
CREATE SCHEMA store;
CREATE TABLE store.shops ("CityId" int REFERENCES "references".cities("Id"),
 "ProvinceId" int REFERENCES "references".provinces("Id"));
INSERT INTO store.shops VALUES (1,1);
CREATE SCHEMA identity;
CREATE TABLE identity.user_addresses (city_id int, province_id int);
INSERT INTO identity.user_addresses VALUES (1,1);
'''


def migration_sql(relative_path):
    return re.findall(r'migrationBuilder\.Sql\(\$?"""(.*?)"""',
                      (ROOT / relative_path).read_text(encoding='utf-8'), re.S)


class TochalSchemaTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.container = 'codex-tochal-schema-' + uuid.uuid4().hex[:12]
        cls.command('run', '--detach', '--network', 'none', '--name', cls.container,
                    '-e', 'POSTGRES_PASSWORD=isolated-test-only', '-e', 'POSTGRES_DB=tochal-db',
                    'postgres:17-alpine')
        cls.addClassCleanup(lambda: cls.command('rm', '-f', cls.container))
        for _ in range(60):
            if cls.command('exec', cls.container, 'pg_isready', '-h', '127.0.0.1', '-U', 'postgres', check=False).returncode == 0:
                break
            time.sleep(.25)
        else:
            raise RuntimeError('Temporary PostgreSQL did not start')
        cls.sql('CREATE DATABASE "wrong-db";', database='postgres')
        cls.sql(FIXTURE, database='wrong-db')
        cls.sql('CREATE ROLE tochal_runtime;')

    @classmethod
    def command(cls, *args, check=True, input=None):
        result = subprocess.run([DOCKER, *args], input=input, capture_output=True,
                                text=True, encoding='utf-8')
        if check and result.returncode:
            raise RuntimeError(result.stderr)
        return result

    @classmethod
    def sql(cls, source, *, database='tochal-db', check=True):
        return cls.command('exec', '-i', cls.container, 'psql', '-X', '-h', '127.0.0.1', '-U', 'postgres',
                           '-d', database, '-v', 'ON_ERROR_STOP=1', '-Atq',
                           check=check, input=source)

    def setUp(self):
        self.sql('DROP SCHEMA IF EXISTS "references", store, identity, hotels, flights CASCADE;')
        self.sql(FIXTURE)

    def test_preserves_data_references_sequences_and_replays(self):
        before = self.sql('SELECT to_jsonb(c) FROM "references".cities c;').stdout
        province_before = self.sql('SELECT to_jsonb(p) FROM "references".provinces p;').stdout
        self.sql(INSTALLER)
        self.sql(INSTALLER)
        self.assertEqual(before, self.sql('SELECT to_jsonb(c)-\'LocationKind\' FROM "references".cities c;').stdout)
        self.assertEqual(province_before, self.sql('SELECT to_jsonb(p)-ARRAY[\'CountryCode\',\'GeoNamesAdmin1Code\',\'IsSynthetic\'] FROM "references".provinces p;').stdout)
        self.assertEqual('1|1\n', self.sql('SELECT * FROM store.shops;').stdout)
        self.assertEqual('1|1\n', self.sql('SELECT * FROM identity.user_addresses;').stdout)
        self.assertEqual('900000\n', self.sql('SELECT last_value FROM "references"."cities_Id_seq";').stdout)
        self.assertEqual('IR|f\n', self.sql('SELECT "CountryCode","IsSynthetic" FROM "references".provinces;').stdout)
        for table in ['references.city_merge_history', 'references.province_reorganization_history',
                      'hotels.snapptrip_city_mappings', 'hotels.lamaso_city_mappings',
                      'hotels.snapptrip_province_mappings', 'hotels.lamaso_province_mappings']:
            schema, name = table.split('.')
            self.assertEqual('0\n', self.sql(f'SELECT count(*) FROM "{schema}"."{name}";').stdout)
        reader = (ROOT / 'src/Refahi.Modules.References.Infrastructure/Repositories/CityGeographyReader.cs').read_text(encoding='utf-8')
        query = re.search(r'"""(.*?)"""', reader, re.S).group(1).replace('@ids', 'ARRAY[1]')
        self.assertIn('1|تهران|Tehran|1|تهران|IR|ایران|Iran|t', self.sql(query).stdout)

    def test_wrong_database_is_rejected_without_changes(self):
        result = self.sql(INSTALLER, database='wrong-db', check=False)
        self.assertNotEqual(0, result.returncode)
        self.assertIn('only for tochal-db', result.stderr)
        self.assertEqual('t\n', self.sql("SELECT to_regclass('\"references\".countries') IS NULL;", database='wrong-db').stdout)

    def test_changed_snapshot_is_rejected_without_changes(self):
        self.sql('UPDATE "references".cities SET "Name"=\'تغییر یافته\';')
        result = self.sql(INSTALLER, check=False)
        self.assertNotEqual(0, result.returncode)
        self.assertIn('snapshot changed', result.stderr)
        self.assertEqual('t\n', self.sql("SELECT to_regclass('\"references\".countries') IS NULL;").stdout)

    def test_country_conflict_rolls_back(self):
        self.sql('ALTER TABLE "references".provinces ADD COLUMN "CountryCode" text DEFAULT \'TR\';')
        self.assertNotEqual(0, self.sql(INSTALLER, check=False).returncode)
        self.assertEqual('t\n', self.sql("SELECT to_regclass('\"references\".countries') IS NULL;").stdout)

    def test_late_failure_rolls_back_all_schema_additions(self):
        self.sql('CREATE SCHEMA hotels; CREATE TABLE hotels.snapptrip_city_mappings(unexpected int);')
        self.assertNotEqual(0, self.sql(INSTALLER, check=False).returncode)
        self.assertEqual('t\n', self.sql("SELECT to_regclass('\"references\".countries') IS NULL;").stdout)
        self.assertEqual('0\n', self.sql("SELECT count(*) FROM information_schema.columns WHERE table_schema='references' AND column_name='CountryCode';").stdout)

    def test_pending_migration_sql_and_foreign_keys(self):
        self.sql(INSTALLER)
        self.sql('CREATE SCHEMA flights; CREATE TABLE flights.airports(iata_code varchar(3) PRIMARY KEY);'
                 'CREATE TABLE flights.search_cities(city_code varchar(3) PRIMARY KEY);')
        flight = migration_sql('src/Refahi.Modules.Flights.Infrastructure/Migrations/20261020152038_FlightGeographyMappings.cs')
        self.sql(flight[0])
        for table, key, parent, parent_key in [('airport_geography_mappings', 'AirportIataCode', 'airports', 'iata_code'),
                                              ('snapptrip_city_mappings', 'ProviderCityCode', 'search_cities', 'city_code')]:
            sql = flight[1]
            for name, value in [('Table', table), ('Key', key), ('Parent', parent), ('ParentKey', parent_key)]:
                sql = sql.replace('{item.' + name + '}', value)
            self.sql(sql)
        hotel = migration_sql('src/Refahi.Modules.Hotels.Infrastructure/Migrations/20261020081100_HotelsReferenceCitySearch.cs')
        self.sql(hotel[0])
        self.sql('CREATE TABLE hotels.catalogue_listings("Provider" text,"NativeCityId" text,"ReferenceCityId" int);')
        self.sql(hotel[1])
        invalid = self.sql('INSERT INTO hotels.lamaso_city_mappings '
                           '("ProviderCityId","CityId","ProviderCityName","CountryCode","MatchMethod","Evidence","SourceSnapshotDate") '
                           'VALUES (\'test\',999,\'test\',\'IR\',\'test\',\'{}\',CURRENT_DATE);', check=False)
        self.assertNotEqual(0, invalid.returncode)
        self.assertIn('foreign key constraint', invalid.stderr)

    def test_runtime_role_visibility_is_repaired_without_write_or_superuser_grants(self):
        self.sql(INSTALLER)
        self.sql('CREATE SCHEMA flights; '
                 'CREATE TABLE flights.airport_geography_mappings(id int); '
                 'CREATE TABLE flights.snapptrip_city_mappings(id int); '
                 'ALTER TABLE flights.airport_geography_mappings OWNER TO tochal_runtime; '
                 'ALTER TABLE flights.snapptrip_city_mappings OWNER TO tochal_runtime; '
                 'GRANT USAGE ON SCHEMA hotels, "references" TO tochal_runtime;')
        guard = migration_sql('src/Refahi.Modules.Hotels.Infrastructure/Migrations/20261020081100_HotelsReferenceCitySearch.cs')[0]
        failed = self.sql('SET ROLE tochal_runtime;' + guard, check=False)
        self.assertNotEqual(0, failed.returncode)
        self.assertIn('Hotel geography V4 must be installed', failed.stderr)
        self.sql(PERMISSIONS)
        self.sql(PERMISSIONS)
        self.sql('SET ROLE tochal_runtime;' + guard)
        self.assertEqual('f|f|f|f\n', self.sql("SELECT rolsuper, rolcreatedb, rolcreaterole, rolbypassrls FROM pg_roles WHERE rolname='tochal_runtime';").stdout)
        self.assertEqual('f\n', self.sql("SELECT has_table_privilege('tochal_runtime','hotels.lamaso_city_mappings','INSERT');").stdout)
        denied = self.sql('SET ROLE tochal_runtime; INSERT INTO "references".countries VALUES (\'XX\',\'test\',\'test\',true);', check=False)
        self.assertNotEqual(0, denied.returncode)

    def test_permission_repair_rejects_ambiguous_runtime_role(self):
        self.sql(INSTALLER)
        self.sql('CREATE SCHEMA flights; '
                 'CREATE TABLE flights.airport_geography_mappings(id int); '
                 'CREATE TABLE flights.snapptrip_city_mappings(id int); '
                 'ALTER TABLE flights.airport_geography_mappings OWNER TO tochal_runtime;')
        failed = self.sql(PERMISSIONS, check=False)
        self.assertNotEqual(0, failed.returncode)
        self.assertIn('Cannot identify one API migration role', failed.stderr)
        self.assertEqual('f\n', self.sql("SELECT has_table_privilege('tochal_runtime','hotels.lamaso_city_mappings','SELECT');").stdout)


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--docker', default='docker')
    args = parser.parse_args()
    DOCKER = args.docker
    unittest.main(argv=[__file__], verbosity=2)
